import{_ as s,o as r,c as e,a2 as o}from"./chunks/framework.CqdVOxXJ.js";const m=JSON.parse('{"title":"13. Shop settings & staff permissions","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/13-admin-shop-settings-and-staff-permissions.md","filePath":"chapters/13-admin-shop-settings-and-staff-permissions.md","lastUpdated":null}'),n={name:"chapters/13-admin-shop-settings-and-staff-permissions.md"};function a(i,t,g,d,h,l){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="_13-shop-settings-staff-permissions" tabindex="-1">13. Shop settings &amp; staff permissions <a class="header-anchor" href="#_13-shop-settings-staff-permissions" aria-label="Permalink to &quot;13. Shop settings &amp; staff permissions&quot;">​</a></h1><p><strong>For:</strong> Shop Owner · <strong>Hub:</strong> Admin (<code>/admin</code>)</p><p>Shop settings decide which gates the app enforces. Change them deliberately: every save is logged, and the rules apply from that moment to every job in the shop.</p><h2 id="_13-1-finding-a-setting-admin-settings" tabindex="-1">13.1 Finding a setting (<code>/admin/settings</code>) <a class="header-anchor" href="#_13-1-finding-a-setting-admin-settings" aria-label="Permalink to &quot;13.1 Finding a setting (`/admin/settings`)&quot;">​</a></h2><p><strong>Admin › Shop settings</strong> is owner-only. It has two areas:</p><ul><li><strong>Shop</strong> — rules for the shop selected in the shop switcher.</li><li><strong>Company</strong> — business-wide lists and details (HQ owner only).</li></ul><p>Pick a section on the left. Each card shows the current values; press <strong>Edit</strong> on the card, change, <strong>Save</strong>. The page URL remembers where you are (<code>?area=shop&amp;section=getting-paid&amp;shop=…</code>), so you can bookmark a section.</p><h2 id="_13-2-shop-area" tabindex="-1">13.2 Shop area <a class="header-anchor" href="#_13-2-shop-area" aria-label="Permalink to &quot;13.2 Shop area&quot;">​</a></h2><h3 id="getting-paid" tabindex="-1">Getting paid <a class="header-anchor" href="#getting-paid" aria-label="Permalink to &quot;Getting paid&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Card</th><th>Settings (defaults)</th></tr></thead><tbody><tr><td><strong>Down payments and holds</strong></td><td><strong>Private / Corporate / Government / Bidding down payment</strong> % (50%) and for each a <strong>blocks</strong> choice: <strong>Does not block</strong>, <strong>Before work</strong>, <strong>Before release</strong>. <strong>Hold car until the customer pays</strong> (on). <strong>Hold car until the insurer pays</strong> (off). <strong>Finance release before the car arrives</strong> (off)</td></tr><tr><td><strong>Payment terms and aging</strong></td><td><strong>Customer</strong>, <strong>Insurer</strong>, <strong>Corporate</strong>, <strong>Government terms</strong> (days); <strong>Aging band 1/2/3</strong> (30 / 60 / 90 days); <strong>Flag bill not transmitted after</strong> (2 days)</td></tr><tr><td><strong>Withholding</strong></td><td><strong>Insurance</strong>, <strong>Corporate</strong>, <strong>Government withholding</strong> %</td></tr><tr><td><strong>GCash, Maya and bank</strong></td><td>Wallet numbers, account names and QR images shown on the customer portal; <strong>Bank accounts</strong> (Bank, Account name, Account number, Code, Particular, Sort, Active)</td></tr></tbody></table><h3 id="workshop-rules" tabindex="-1">Workshop rules <a class="header-anchor" href="#workshop-rules" aria-label="Permalink to &quot;Workshop rules&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Card</th><th>Settings (defaults)</th></tr></thead><tbody><tr><td><strong>Quality check</strong></td><td><strong>QC photos required</strong> (4), <strong>Insurance needs an LOA</strong> (on), <strong>Depreciation reduces insurer share</strong> (off), <strong>Participation and betterment reduce insurer share</strong> (off)</td></tr><tr><td><strong>Paperwork by customer type</strong></td><td><strong>Corporate needs an approved PO</strong>, <strong>Government needs a PO or blanket PO</strong>, <strong>Bidding needs an award</strong>, <strong>Government needs a BAC resolution</strong> (all off)</td></tr><tr><td><strong>Insurance release of claim</strong></td><td><strong>Release of claim wording</strong> printed on insurance releases</td></tr><tr><td><strong>Storage fees</strong></td><td><strong>Free days after ready</strong> (7), <strong>Daily storage rate</strong> (blank = no storage charge)</td></tr><tr><td><strong>Contractors</strong></td><td><strong>Warn before commitment date</strong> (0 days), <strong>Contractor signature required to complete</strong> (off), <strong>Prefill scope from the job work category</strong> (on)</td></tr></tbody></table><h3 id="buying" tabindex="-1">Buying <a class="header-anchor" href="#buying" aria-label="Permalink to &quot;Buying&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Card</th><th>Settings (defaults)</th></tr></thead><tbody><tr><td><strong>Supplier terms</strong></td><td><strong>Default terms</strong> (COD / Term / From Rakkii stock; COD), <strong>Default term days</strong> (30)</td></tr><tr><td><strong>Supplier bills and expenses</strong></td><td><strong>Due-soon warning</strong> (3 days), <strong>Post supplier payments to expenses</strong> (on), <strong>Expense category</strong></td></tr></tbody></table><h3 id="sales-commission" tabindex="-1">Sales &amp; commission <a class="header-anchor" href="#sales-commission" aria-label="Permalink to &quot;Sales &amp; commission&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Card</th><th>Settings (defaults)</th></tr></thead><tbody><tr><td><strong>Minimum gross margin</strong></td><td><strong>Minimum gross margin</strong> (30%), <strong>When a job is below the minimum</strong>: <strong>Warn</strong> or <strong>Block</strong></td></tr><tr><td><strong>Sales performer</strong></td><td><strong>Performer at or above quota</strong> (100%)</td></tr><tr><td><strong>Sales figures</strong></td><td><strong>Leave these statuses out of sales figures</strong> (Cancelled, No-show)</td></tr><tr><td><strong>Agent commission</strong></td><td><strong>Agent commission on</strong>, <strong>Agent rate</strong> (5%), <strong>Agent is a fixed peso amount</strong>, <strong>Due days after release</strong> (30), <strong>Basis</strong>: <strong>Customer paid</strong>, <strong>Approved amount</strong> or <strong>Net of cost</strong></td></tr><tr><td><strong>Commission floor and channels</strong></td><td><strong>Minimum gross</strong> (₱30,000), <strong>Waive every line when gross is under the floor</strong>, <strong>Margin haircut</strong> (30%), <strong>Tax</strong> %, <strong>No in-house referral commission from</strong> (walk-in, phone, Messenger, web)</td></tr><tr><td><strong>Outside agent fee</strong></td><td><strong>Agent fee enabled</strong>, <strong>Default mode</strong> (None / Percent / Fixed), <strong>Default value</strong>, <strong>Agent fee tax</strong>, <strong>Due when</strong> (Released / Customer paid / Immediately), <strong>Post agent fees to expenses</strong>, <strong>Walk-ins eligible</strong></td></tr></tbody></table><h3 id="staff-time" tabindex="-1">Staff &amp; time <a class="header-anchor" href="#staff-time" aria-label="Permalink to &quot;Staff &amp; time&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Card</th><th>Settings</th></tr></thead><tbody><tr><td><strong>Clock-in</strong></td><td><strong>Map pin latitude / longitude</strong>, <strong>Allowed radius</strong>, <strong>Photo required on clock-in and clock-out</strong>, <strong>Off-site punch with approval</strong></td></tr><tr><td><strong>Week and minimum wage</strong></td><td><strong>Week starts on</strong>, <strong>Minimum daily wage</strong></td></tr><tr><td><strong>Holiday and night pay</strong></td><td>Summary only — edited on <strong>HR › Payroll › Holidays &amp; premiums</strong></td></tr><tr><td><strong>KPI scorecards</strong></td><td><strong>Scorecard period</strong> (Yearly)</td></tr></tbody></table><h3 id="customer-site" tabindex="-1">Customer site <a class="header-anchor" href="#customer-site" aria-label="Permalink to &quot;Customer site&quot;">​</a></h3><p><strong>Shop page</strong> (<strong>Hours</strong>, <strong>Facebook URL</strong>) and <strong>Service reminder emails</strong>.</p><h3 id="advanced-one-time-setup" tabindex="-1">Advanced (one-time setup) <a class="header-anchor" href="#advanced-one-time-setup" aria-label="Permalink to &quot;Advanced (one-time setup)&quot;">​</a></h3><p><strong>Invoice numbering</strong> (<strong>VAT invoice prefix</strong>, <strong>Non-VAT invoice prefix</strong>), <strong>Payment account mapping</strong> (which money account receives Cash, GCash, Maya, Bank and Card payments), and <strong>Demo branch</strong> (<strong>Enable demo branch</strong> for test bookings and onboarding at <code>/b/demo</code>, kept apart from live data).</p><div class="info custom-block"><p class="custom-block-title">📷 Screenshot placeholder</p><p><code>/screenshots/13-admin-shop-settings-and-staff-permissions/01-shop-settings.png</code> — Shop settings, Getting paid section with Down payments and holds card.</p></div><h2 id="_13-3-company-area-hq-owner" tabindex="-1">13.3 Company area (HQ owner) <a class="header-anchor" href="#_13-3-company-area-hq-owner" aria-label="Permalink to &quot;13.3 Company area (HQ owner)&quot;">​</a></h2><ul><li><strong>Business details</strong> — <strong>Legal name</strong>, <strong>TIN</strong>, <strong>Facebook</strong> (letterheads and documents).</li><li><strong>Shops</strong> — every branch: <strong>Switch to this shop</strong>, <strong>Edit</strong>, <strong>Turn off</strong>, <strong>Add a shop</strong>, <strong>Add owner for this shop</strong>.</li><li><strong>Lists</strong> — <strong>Part grades</strong>, <strong>Part categories</strong>, <strong>Work categories</strong>, <strong>Expense categories</strong>, and <strong>Checklist templates</strong> (<strong>Add checklist</strong> with a <strong>Name</strong> and <strong>Lines</strong>; <strong>Archive</strong> old ones). Tip: create a &quot;Release prep&quot; template (customer signed acceptance form, old parts returned, car washed and vacuumed) — see <a href="/rakkii-cars-guide/chapters/05-lane-1-private-walk-in-jobs">Chapter 5</a>.</li><li><strong>Customer site</strong> — public services list, message templates and reminders.</li><li><strong>KPI definitions</strong> — scorecard items: <strong>Name</strong>, <strong>Applies to role</strong>, <strong>Weight %</strong>, <strong>Target</strong>. These feed the scorecards in <a href="/rakkii-cars-guide/chapters/11-hr-payroll-kiosk-announcements-documents">Chapter 11</a>.</li></ul><h2 id="_13-4-staff-access-and-pay-admin-staff" tabindex="-1">13.4 Staff access and pay (<code>/admin/staff</code>) <a class="header-anchor" href="#_13-4-staff-access-and-pay-admin-staff" aria-label="Permalink to &quot;13.4 Staff access and pay (`/admin/staff`)&quot;">​</a></h2><p>Menu label <strong>Staff and pay</strong>; page title <strong>Access and pay</strong>. People list: <strong>Name</strong>, <strong>Home shop</strong>, <strong>Role</strong>, <strong>Permissions</strong>, <strong>Pay</strong>, <strong>Status</strong> (<strong>Active</strong>, <strong>Waiting for first login</strong>, <strong>Inactive</strong>). Actions: <strong>Edit</strong>, <strong>Deactivate</strong> / <strong>Activate</strong>, <strong>Resend invite</strong>.</p><h3 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Role</th><th>Use for</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Owner</strong></td><td>Shop owner</td><td>Full access; does not clock; the only one who changes roles</td></tr><tr><td><strong>Admin</strong></td><td>Office / service advisor</td><td>To be decided — Waiting for confirmation</td></tr><tr><td><strong>Technician</strong></td><td>Lead technician and bay staff</td><td>Sees My jobs, Me hub</td></tr><tr><td><strong>Sales</strong></td><td>Sales agents</td><td>Sales hub and pipeline only</td></tr></tbody></table><h3 id="permission-switches" tabindex="-1">Permission switches <a class="header-anchor" href="#permission-switches" aria-label="Permalink to &quot;Permission switches&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Switch</th><th>What it allows</th><th>Typical</th></tr></thead><tbody><tr><td><strong>Can canvass &amp; pay suppliers</strong></td><td>Fill the Canvass tab, record Parts buy payments</td><td>Lead technician on; Sales off</td></tr><tr><td><strong>Can open LOA PDF</strong></td><td>Open the insurer&#39;s LOA document</td><td>Admin on; Sales off. Turning this on does <strong>not</strong> reveal pesos</td></tr><tr><td><strong>Can see LOA pesos / job margin</strong></td><td>See approved LOA amounts and job margin</td><td>Owner/trusted staff only</td></tr><tr><td><strong>Must clock</strong></td><td>Must use the time clock to be paid</td><td>On for technicians and front desk; off for sales; owner never clocks</td></tr></tbody></table><p><strong>Setting up a new staff member:</strong> add them in <strong>HR › Directory</strong> (or <strong>Edit</strong> here), choose <strong>Role</strong> and <strong>Home shop</strong>, set the four switches, set the pay rate, then send / <strong>Resend invite</strong>. They sign in with their email (<a href="/rakkii-cars-guide/chapters/01-welcome-and-navigation">Chapter 1</a>).</p><p><strong>When someone leaves:</strong> <strong>Deactivate</strong> (from HR Directory to also move open jobs), then generate their final pay and quitclaim (<a href="/rakkii-cars-guide/chapters/11-hr-payroll-kiosk-announcements-documents">Chapter 11</a>).</p>',33)])])}const p=s(n,[["render",a]]);export{m as __pageData,p as default};
